import Foundation

/// What Studio knows about a model before Review for Printing with Claude looks at it: where it came from, the size the
/// seller wants, and findings from elsewhere (such as Meshy's printability analysis). Memory only.
struct PrintReviewContext: Equatable, Sendable {
    /// For example "Generated by Meshy from a photo"; empty for a library model the seller picked.
    var origin: String = ""
    /// For example "Height should be 120 mm (typed by the seller)".
    var intendedSizeNote: String?
    /// "Display piece" or "Functional part", when the seller said.
    var purpose: String?
    /// One line each, shown to the seller and sent to Claude with the review.
    var findings: [String] = []
}

/// Opens Review for Printing with Claude for a library model (`StudioStore.printReviewRequest`).
struct PrintReviewRequest: Identifiable, Equatable {
    let id = UUID()
    let modelID: UUID
    var context = PrintReviewContext()
}
